import java.io.BufferedInputStream
import java.io.StreamTokenizer

const val MOD = 1000000007L

val dp = Array(55) { Array(55) { LongArray(205) } }
val c = Array(55) { LongArray(55) }

fun main() {
    val st = StreamTokenizer(BufferedInputStream(System.`in`))
    fun ni(): Int { st.nextToken(); return st.nval.toInt() }

    val n = ni()
    val lim = ni()
    var A = 0
    var B = 0
    for (i in 0 until n) {
        val fk = ni()
        if (fk == 50) A++ else B++
    }
    dp[A][B][0] = 1
    c[0][0] = 1
    for (i in 1..50) {
        for (j in 0..i) {
            c[i][j] = (if (j > 0) c[i - 1][j - 1] else 0L) + c[i - 1][j]
        }
    }
    for (k in 1..4 * n) {
        for (i in A downTo 0) {
            for (j in B downTo 0) {
                val s = k % 2
                dp[i][j][k] = 0
                if (s != 0) {
                    for (ii in i..A) {
                        var f = lim - (ii - i) * 50
                        if (f >= 0) {
                            f /= 100
                            f += j
                            f = minOf(f, B)
                            for (jj in j..f) {
                                if (i != ii || j != jj) {
                                    dp[i][j][k] += (dp[ii][jj][k - 1] * c[ii][ii - i] * c[jj][jj - j]) % MOD
                                    dp[i][j][k] %= MOD
                                }
                            }
                        }
                    }
                } else {
                    for (ii in 0..i) {
                        var f = lim - (i - ii) * 50
                        if (f >= 0) {
                            f /= 100
                            f = maxOf(j - f, 0)
                            for (jj in f..j) {
                                if (i != ii || j != jj) {
                                    dp[i][j][k] += (dp[ii][jj][k - 1] * c[A - ii][i - ii] * c[B - jj][j - jj]) % MOD
                                    dp[i][j][k] %= MOD
                                }
                            }
                        }
                    }
                }
                if (dp[0][0][k] != 0L) {
                    println(k)
                    println(dp[0][0][k])
                    return
                }
            }
        }
    }
    println("-1\n0")
}
